svg.script:
/**/
(function() {
  'use strict';

  var currentState = 0; // 0: Sem chão, 1: Fáscia, 2: Diafragma, 3: Períneo, 4: Full (3)
  var currentFocus = null; // null or 1, 2, 3

  var stateData = {
    0: {
      title: 'ESTADO 0: SEM CHÃO',
      badge: 'FALHA DE SUPORTE',
      l1: 'Sem o suporte das camadas pélvicas, as vísceras',
      l2: 'sofrem descida gravitacional direta (prolapso).',
      l3: 'Os vetores de falha (em vermelho) apontam para a',
      l4: 'exteriorização pelo hiato desprovido de chão.',
      density: '0 / 3 camadas ativas (Assoalho Ausente)',
      cHeader: 'INTERPRETAÇÃO CLÍNICA',
      cL1: 'Ausência total de sustentação passiva e ativa.',
      cL2: 'Modelagem de risco máximo para disfunção do compartimento',
      cL3: 'anterior, médio e posterior (POP-Q estágio IV).',
      cColor: 'var(--a12-alerta, var(--a12p14-hero-falha, #D85C6A))',
      visceraShift: 'translate(0, 32px)',
      stepperWidth: '0px'
    },
    1: {
      title: 'ESTADO 1: FÁSCIA ENDOPÉLVICA',
      badge: 'CAMADA PROFUNDA (SUSPENSÃO)',
      l1: 'A fáscia endopélvica (ATFP, lig. uterossacrais e',
      l2: 'fáscia pubocervical/retovaginal) ancora a cúpula',
      l3: 'e paredes vaginais às paredes pélvicas ósseas.',
      l4: 'Primeiro nível de suspensão visceral passiva (Nível I/II DeLancey).',
      density: '1 / 3 camadas ativas (Sustentação Fásica)',
      cHeader: 'EFICIÊNCIA MECÂNICA C1',
      cL1: 'Estabilização apical e suspensão fascial estabelecida.',
      cL2: 'Impede o colapso visceral direto, mas ainda requer',
      cL3: 'o suporte muscular dinâmico e fecho perineal.',
      cColor: 'var(--a12-fascia-endopelvica, var(--a12p14-hero-fascia, #6FA8D6))',
      visceraShift: 'translate(0, 0px)',
      stepperWidth: '83px'
    },
    2: {
      title: 'ESTADO 2: DIAFRAGMA PÉLVICO',
      badge: 'CAMADA INTERMEDIÁRIA (SUSTENTAÇÃO)',
      l1: 'O M. Levantador do Ânus (puborretal, pubococcígeo',
      l2: 'e iliococcígeo) forma a prateleira muscular.',
      l3: 'Mantém o hiato urogenital fechado e eleva as',
      l4: 'vísceras em direção à símfise púbica (tração anterior).',
      density: '2 / 3 camadas ativas (Sustentação Muscular)',
      cHeader: 'EFICIÊNCIA MECÂNICA C1 + C2',
      cL1: 'Tônus muscular ativo sustenta 70% da carga pélvica.',
      cL2: 'A fáscia permanece íntegra sob menor tensão',
      cL3: 'graças ao suporte em funil do diafragma pélvico.',
      cColor: 'var(--a12-diafragma-pelvico, var(--a12p14-hero-diafragma, #55B889))',
      visceraShift: 'translate(0, 0px)',
      stepperWidth: '166px'
    },
    3: {
      title: 'ESTADO 3: REGIÃO PERINEAL',
      badge: 'CAMADA SUPERFICIAL (FECHO & ANCORAGEM)',
      l1: 'A membrana do períneo, corpo perineal e esfíncteres',
      l2: 'promovem o fechamento inferior do trígono UG.',
      l3: 'Ancoram o plano distal na pele e centro tendíneo,',
      l4: 'garantindo a continência e integridade do assoalho.',
      density: '3 / 3 camadas ativas (Assoalho COMPLETO)',
      cHeader: 'ASSOALHO PÉLVICO ÍNTEGRO (C1 + C2 + C3)',
      cL1: 'Sustentação cumulativa tridimensional perfeita.',
      cL2: 'As 3 camadas somam forças sem se anular:',
      cL3: 'Suspensão (C1) + Prateleira (C2) + Fecho Distal (C3).',
      cColor: 'var(--a12-regiao-perineal, var(--a12p14-hero-perineo, #EF7582))',
      visceraShift: 'translate(0, 0px)',
      stepperWidth: '250px'
    }
  };

  function updateUI() {
    // Update Viscera position & Fail Vectors
    var visceraGrp = document.getElementById('a12p14-hero-viscera-grp');
    var failVectors = document.getElementById('a12p14-hero-fail-vectors');

    var effectiveState = (currentState === 4) ? 3 : currentState;
    var data = stateData[effectiveState];

    if (visceraGrp) {
      visceraGrp.style.transform = data.visceraShift;
    }

    if (failVectors) {
      failVectors.style.opacity = (effectiveState === 0) ? '1' : '0';
      failVectors.style.pointerEvents = (effectiveState === 0) ? 'auto' : 'none';
    }

    // Update Cumulative Layers Visibility
    for (var l = 1; l <= 3; l++) {
      var layerEl = document.getElementById('a12p14-hero-layer-' + l);
      if (layerEl) {
        var isBuilt = (effectiveState >= l);
        if (!isBuilt) {
          layerEl.classList.add('is-hidden');
          layerEl.classList.remove('is-dimmed');
        } else {
          layerEl.classList.remove('is-hidden');
          if (currentFocus !== null && currentFocus !== l) {
            layerEl.classList.add('is-dimmed');
          } else {
            layerEl.classList.remove('is-dimmed');
          }
        }
      }
    }

    // Update Stepper Progress Bar & Dots
    var progressBar = document.getElementById('a12p14-hero-stepper-progress');
    if (progressBar) {
      progressBar.style.x2 = data.stepperWidth;
    }

    for (var s = 0; s <= 3; s++) {
      var stepDot = document.getElementById('a12p14-hero-step-' + s);
      if (stepDot) {
        var circle = stepDot.querySelector('circle');
        if (circle) {
          if (s <= effectiveState) {
            circle.setAttribute('fill', 'var(--a12-ouro, var(--a12p14-hero-eixo, #F3BE5B))');
            circle.setAttribute('stroke', 'var(--a12-ouro, var(--a12p14-hero-eixo, #F3BE5B))');
          } else {
            circle.setAttribute('fill', 'var(--a12-card-bg, var(--a12p14-hero-card-bg, #1E1822))');
            circle.setAttribute('stroke', 'var(--a12-border, var(--a12p14-hero-border, #382C3D))');
          }
        }
      }
    }

    // Update Control Buttons Active State
    var btns = document.querySelectorAll('.a12p14-hero-btn');
    btns.forEach(function(btn) {
      var st = btn.getAttribute('data-state');
      if ((st === 'full' && currentState === 4) || (parseInt(st, 10) === currentState)) {
        btn.classList.add('is-active');
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.classList.remove('is-active');
        btn.setAttribute('aria-pressed', 'false');
      }
    });

    // Update Side Panel Texts
    document.getElementById('a12p14-hero-panel-state-title').textContent = data.title;
    document.getElementById('a12p14-hero-panel-level-tag').textContent = data.badge;
    document.getElementById('a12p14-hero-panel-line-1').textContent = data.l1;
    document.getElementById('a12p14-hero-panel-line-2').textContent = data.l2;
    document.getElementById('a12p14-hero-panel-line-3').textContent = data.l3;
    document.getElementById('a12p14-hero-panel-line-4').textContent = data.l4;
    document.getElementById('a12p14-hero-panel-density').textContent = data.density;

    document.getElementById('a12p14-hero-conclusion-header').textContent = data.cHeader;
    document.getElementById('a12p14-hero-conclusion-header').style.fill = data.cColor;
    document.getElementById('a12p14-hero-conclusion-line-1').textContent = data.cL1;
    document.getElementById('a12p14-hero-conclusion-line-2').textContent = data.cL2;
    document.getElementById('a12p14-hero-conclusion-line-3').textContent = data.cL3;

    var concBg = document.getElementById('a12p14-hero-conclusion-bg');
    if (concBg) {
      concBg.style.stroke = data.cColor;
    }
  }

  function setState(st) {
    currentState = st;
    currentFocus = null; // reset isolated focus on state change
    updateUI();
  }

  function toggleFocus(layerNum) {
    if (currentState < layerNum) {
      // If layer not yet built, build up to this layer!
      currentState = layerNum;
      currentFocus = null;
    } else {
      // Toggle focus/isolate mode
      if (currentFocus === layerNum) {
        currentFocus = null;
      } else {
        currentFocus = layerNum;
      }
    }
    updateUI();
  }

  // Attach Event Listeners to Buttons
  var btns = document.querySelectorAll('.a12p14-hero-btn');
  btns.forEach(function(btn) {
    var handler = function(e) {
      e.preventDefault();
      var st = btn.getAttribute('data-state');
      if (st === 'full') {
        setState(4);
      } else {
        setState(parseInt(st, 10));
      }
    };
    btn.addEventListener('click', handler);
    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        handler(e);
      }
    });
  });

  // Attach Event Listeners to Layer Shapes
  for (var l = 1; l <= 3; l++) {
    (function(layerNum) {
      var layerEl = document.getElementById('a12p14-hero-layer-' + layerNum);
      if (layerEl) {
        var handler = function(e) {
          e.preventDefault();
          e.stopPropagation();
          toggleFocus(layerNum);
        };
        layerEl.addEventListener('click', handler);
        layerEl.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            handler(e);
          }
        });
      }
    })(l);
  }

  // Initialize
  setState(0);
})();
/**/
